            df_div(df_mul(df_add(vec2(2.2157000785227865e-05, -7.8522786349836081e-13),
                                 df_mul(vec2(1.5499999506118911e-07, 4.93881088742341e-15), temperature_c)),
                          vec2(100000, 0)),
                   pressure_pa);
        vec2 dynamic_viscosity =
            df_mul(df_mul(vec2(1.720000000204891e-05, -2.0489083249041612e-15),
                          df_div(vec2(393, 0), df_add(temperature_k, vec2(120, 0)))),
                   power(df_div(temperature_k, vec2(273.14999389648438, 6.1035156022626325e-06)), vec2(1.5, 0)));
        result.kinematic_viscosity  = df_div(dynamic_viscosity, density);
        result.schmidt_one_third    = cube_root(df_div(result.kinematic_viscosity, result.vapor_diffusivity));
        result.thermal_conductivity = df_add(vec2(0.02397100068628788, -6.862878806912498e-10),
                                             df_mul(vec2(7.7999997301958501e-05, 2.6980414972489764e-12), temperature_c));
        result.density_factor       = df_sqrt(df_div(vec2(1.2250000238418579, -2.3841857821338408e-08), density));
        return result;
