        vec2 gc12          = gamma_value(df_add(df_add(df_div(vec2(2, 0), cold.mu_cloud), vec2(1, 0)), cold.alpha_cloud));
        vec2 gc13          = gamma_value(df_add(df_add(df_div(vec2(3, 0), cold.mu_cloud), vec2(1, 0)), cold.alpha_cloud));
        vec2 gc14          = gamma_value(df_add(df_add(df_div(vec2(4, 0), cold.mu_cloud), vec2(1, 0)), cold.alpha_cloud));
        vec2 gc15          = gamma_value(df_add(df_add(df_div(vec2(5, 0), cold.mu_cloud), vec2(1, 0)), cold.alpha_cloud));
        vec2 gx1           = gamma_value(df_add(vec2(1, 0), alpha));
