    void route_collision(vec2              first_mass,
                         vec2              second_mass,
                         vec2              first_number,
                         vec2              second_number,
                         GammaDistribution frozen_psd,
                         vec2              frozen_bulk_density,
                         int               destination)
    {
        vec2 total_mass = df_add(first_mass, second_mass);
        if ((!ml_greater(total_mass, vec2(0, 0))))
            return;
        vec2 maximum_diameter = maximum(frozen_psd.mean_mass_diameter, cold.rain_psd.mean_mass_diameter);
        if ((!ml_greater(maximum_diameter, vec2(0, 0))))
            return;
        vec2 destination_density = vec2(400, 0);
        if ((destination == 0))
            destination_density = frozen_bulk_density;
        else if ((destination == 2))
            destination_density = vec2(900, 0);
        vec2 combined_number =
            df_div(total_mass,
                   df_mul(df_mul(df_mul(df_mul(destination_density, df_div(cold.pi, vec2(6, 0))), maximum_diameter),
                                 maximum_diameter),
                          maximum_diameter));
        vec2 admitted_number = minimum(combined_number, minimum(first_number, second_number));
        if ((destination == 0))
        {
            cold.collision_mass_to_snow   = df_add(cold.collision_mass_to_snow, total_mass);
            cold.collision_number_to_snow = df_add(cold.collision_number_to_snow, admitted_number);
        }
        else if ((destination == 1))
        {
            cold.collision_mass_to_graupel   = df_add(cold.collision_mass_to_graupel, total_mass);
            cold.collision_number_to_graupel = df_add(cold.collision_number_to_graupel, admitted_number);
        }
        else
        {
            cold.collision_mass_to_hail   = df_add(cold.collision_mass_to_hail, total_mass);
            cold.collision_number_to_hail = df_add(cold.collision_number_to_hail, admitted_number);
        }
    }
